<?php
require_once __DIR__.'/../config/auth.php';require_role('owner');$pageTitle='Manajemen Promo';$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=(string)($_POST['action']??'');try{if($action==='save'){$id=(int)($_POST['id']??0);$code=strtoupper(preg_replace('/\s+/','',trim((string)($_POST['kode']??''))));$type=(string)($_POST['tipe']??'persen');$value=max(0,(float)($_POST['nilai']??0));$min=max(0,(float)($_POST['min_belanja']??0));$quota=max(0,(int)($_POST['kuota']??0));$start=trim((string)($_POST['mulai']??''));$end=trim((string)($_POST['selesai']??''));$active=isset($_POST['is_active'])?1:0;if(!preg_match('/^[A-Z0-9_-]{3,40}$/',$code))throw new RuntimeException('kode promo harus 3–40 karakter, hanya huruf, angka, minus, atau underscore.');if(!in_array($type,['persen','nominal'],true))throw new RuntimeException('tipe promo tidak valid.');if($type==='persen'&&$value>100)throw new RuntimeException('diskon persen maksimal 100%.');$start=$start!==''?str_replace('T',' ',$start).(strlen($start)===16?':00':''):null;$end=$end!==''?str_replace('T',' ',$end).(strlen($end)===16?':00':''):null;if($start&&$end&&strtotime($end)<strtotime($start))throw new RuntimeException('waktu selesai harus sesudah waktu mulai.');if($id){$st=$pdo->prepare('UPDATE promos SET kode=?,tipe=?,nilai=?,min_belanja=?,kuota=?,mulai=?,selesai=?,is_active=? WHERE id=?');$st->execute([$code,$type,$value,$min,$quota,$start,$end,$active,$id]);log_activity('update_promo',$code);$message='promo diperbarui.';}else{$st=$pdo->prepare('INSERT INTO promos (kode,tipe,nilai,min_belanja,kuota,mulai,selesai,is_active) VALUES (?,?,?,?,?,?,?,?)');$st->execute([$code,$type,$value,$min,$quota,$start,$end,$active]);log_activity('create_promo',$code);$message='promo dibuat.';}}elseif($action==='delete'){$id=(int)$_POST['id'];$st=$pdo->prepare('DELETE FROM promos WHERE id=?');$st->execute([$id]);log_activity('delete_promo','ID '.$id);$message='promo dihapus.';}}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'promo gagal disimpan. kode mungkin sudah digunakan.';}}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM promos WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$promos=dbq('SELECT p.*,(SELECT COUNT(*) FROM promo_usages pu WHERE pu.promo_id=p.id) used FROM promos p ORDER BY p.created_at DESC')->fetchAll();$asLocal=fn($d)=>$d?date('Y-m-d\TH:i',strtotime($d)):'';require __DIR__.'/../includes/admin-header.php'; ?>
<?php if($message):?><div class="flash flash-ok"><?= h($message) ?></div><?php endif;?><?php if($error):?><div class="flash flash-error"><?= h($error) ?></div><?php endif;?><div class="grid xl:grid-cols-[380px_1fr] gap-5 items-start"><section class="card p-5"><h2 class="font-serif text-2xl"><?= $edit?'Edit promo':'Buat promo' ?></h2><form method="post" class="space-y-4 mt-5"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div><label class="field-label">Kode promo</label><input class="field uppercase" name="kode" required maxlength="40" value="<?= h($edit['kode']??'') ?>" placeholder="NGOPI10"></div><div class="grid grid-cols-2 gap-3"><div><label class="field-label">Tipe diskon</label><select class="field" name="tipe"><option value="persen" <?= ($edit['tipe']??'persen')==='persen'?'selected':'' ?>>Persen (%)</option><option value="nominal" <?= ($edit['tipe']??'')==='nominal'?'selected':'' ?>>Nominal (Rp)</option></select></div><div><label class="field-label">Nilai diskon</label><input class="field" type="number" name="nilai" min="0" step="1" required value="<?= h($edit['nilai']??'10') ?>"></div></div><div><label class="field-label">Minimal belanja (Rp)</label><input class="field" type="number" name="min_belanja" min="0" step="1000" value="<?= h($edit['min_belanja']??'0') ?>"></div><div><label class="field-label">Kuota penggunaan</label><input class="field" type="number" name="kuota" min="0" value="<?= h($edit['kuota']??'100') ?>"><p class="text-xs text-coffee/50 mt-1">0 = tanpa batas.</p></div><div><label class="field-label">Mulai (opsional)</label><input class="field" type="datetime-local" name="mulai" value="<?= h($asLocal($edit['mulai']??null)) ?>"></div><div><label class="field-label">Selesai (opsional)</label><input class="field" type="datetime-local" name="selesai" value="<?= h($asLocal($edit['selesai']??null)) ?>"></div><label class="text-sm flex items-center gap-2"><input type="checkbox" name="is_active" class="accent-[#8A9A5B]" <?= !isset($edit['is_active'])||(int)$edit['is_active']===1?'checked':'' ?>> Aktif</label><button class="btn btn-coffee w-full">Simpan promo</button><?php if($edit):?><a class="block text-sm text-center underline" href="<?= h(BASE_URL) ?>/admin/promos.php">Batal edit</a><?php endif;?></form></section><section class="card p-5"><h2 class="font-serif text-2xl">Daftar promo</h2><div class="table-wrap mt-4"><table class="admin-table"><thead><tr><th>Kode</th><th>Diskon</th><th>Minimal</th><th>Terpakai</th><th>Periode</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($promos as $p):$valid=!(int)$p['is_active']?false:(!$p['mulai']||strtotime($p['mulai'])<=time())&&(!$p['selesai']||strtotime($p['selesai'])>=time())&&(!(int)$p['kuota']||(int)$p['used']<(int)$p['kuota']);?><tr><td><b><?= h($p['kode']) ?></b></td><td><?= $p['tipe']==='persen'?h($p['nilai']).'%':money($p['nilai']) ?></td><td><?= money($p['min_belanja']) ?></td><td><?= (int)$p['used'] ?>/<?= (int)$p['kuota']?:'∞' ?></td><td class="text-xs"><?= h($p['mulai']?:'Tanpa awal') ?><br>— <?= h($p['selesai']?:'Tanpa akhir') ?></td><td><span class="status-pill <?= $valid?'status-green':'status-red' ?>"><?= $valid?'Aktif':'Nonaktif' ?></span></td><td><div class="flex flex-col gap-2"><a class="underline text-xs" href="?edit=<?= (int)$p['id'] ?>">Edit</a><form method="post" onsubmit="return confirm('Hapus promo ini?')"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="text-xs text-red-700 underline">Hapus</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require __DIR__.'/../includes/admin-footer.php'; ?>
